func TestLerp(t *testing.T) {
	cases := []struct {
		name    string
		a, b, t float64
		want    float64
	}{
		{"t=0 returns a", 0, 10, 0, 0},
		{"t=1 returns b", 0, 10, 1, 10},
		{"t=0.5 midpoint", 0, 10, 0.5, 5},
		{"negative range", -10, 10, 0.5, 0},
		{"extrapolate beyond 1", 0, 10, 2, 20},
		{"extrapolate below 0", 0, 10, -1, -10},
		{"a equals b", 5, 5, 0.5, 5},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := Lerp(c.a, c.b, c.t)
			if got != c.want {
				t.Errorf("Lerp(%v, %v, %v) = %v, want %v", c.a, c.b, c.t, got, c.want)
			}
		})
	}
}

